import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not script_path or not os.path.exists(script_path):
        raise OSError("Invalid script path")
    proc = subprocess.Popen(["bash", script_path])
    ps_proc = psutil.Process(proc.pid)
    cpu_usage = 0.0
    mem_usage = 0
    elapsed = 0.0
    interval = 0.1
    try:
        ps_proc.cpu_percent(interval=None)
    except (psutil.NoSuchProcess, psutil.ZombieProcess):
        proc.wait(timeout=1)
        return {"CPU Usage": cpu_usage, "Memory Usage": mem_usage}
    while True:
        if proc.poll() is not None:
            break
        if elapsed >= timeout:
            try:
                proc.terminate()
            except Exception:
                pass
            try:
                proc.wait(timeout=1)
            except Exception:
                try:
                    proc.kill()
                except Exception:
                    pass
            break
        time.sleep(interval)
        elapsed += interval
        try:
            status = ps_proc.status()
            if status == psutil.STATUS_ZOMBIE:
                break
            cpu = ps_proc.cpu_percent(interval=None)
            mem = ps_proc.memory_info().rss
            cpu_usage += cpu
            mem_usage += mem
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break
    try:
        proc.wait(timeout=1)
    except Exception:
        pass
    return {"CPU Usage": cpu_usage, "Memory Usage": mem_usage}

